beforeExample:
class TestClass {
    public String concat(String s1, String s2) {
        StringBuffer buf = new StringBuffer(s1); // Should match
        buf.append(s2);
        return buf.toString();
    }

    public void log(Object... messages) {
        StringBuffer logBuffer = new StringBuffer(); // Should match
        for (Object msg : messages) {
            logBuffer.append(msg);
        }
        System.out.println(logBuffer.toString());
    }

    private StringBuffer fieldBuffer = new StringBuffer("field"); // Should NOT match - not local variable
    public void modifyField() {
        fieldBuffer.append(" modified");
    }

    public void processExternalBuffer(StringBuffer externalBuf) { // Should NOT match - parameter
        externalBuf.append(" processed");
    }

    public void passDirectly() {
        someMethod(new StringBuffer("direct")); // Should NOT match - not assigned to a local variable
    }

    private void someMethod(StringBuffer b) {}
}

