class TestClass {
    public String concat(String s1, String s2) {
        StringBuilder buf = new StringBuilder(s1); // Transformed
        buf.append(s2);
        return buf.toString();
    }

    public void log(Object... messages) {
        StringBuilder logBuffer = new StringBuilder(); // Transformed
        for (Object msg : messages) {
            logBuffer.append(msg);
        }
        System.out.println(logBuffer.toString());
    }

    private StringBuffer fieldBuffer = new StringBuffer("field"); // No change
    public void modifyField() {
        fieldBuffer.append(" modified");
    }

    public void processExternalBuffer(StringBuffer externalBuf) { // No change
        externalBuf.append(" processed");
    }

    public void passDirectly() {
        someMethod(new StringBuffer("direct")); // No change
    }

    private void someMethod(StringBuffer b) {}
}

negativeExample:
class NegativeTestClass {
    // StringBuffer as a field - should not be converted
    private StringBuffer fieldBuffer = new StringBuffer("field");
    public void modifyField() {
        fieldBuffer.append(" modified");
    }

    // StringBuffer as a method parameter - should not be converted
    public void processExternalBuffer(StringBuffer externalBuf) {
        externalBuf.append(" processed");
    }

    // StringBuffer instantiated and passed directly to a method - should not be converted
    public void passDirectly() {
        someMethod(new StringBuffer("direct"));
    }

    private void someMethod(StringBuffer b) {}
}
